import http from 'node:http';
import { normalizeDueDate } from './due-dates.js';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(name) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK (length(title) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
`);
// Upgrade databases created before project archiving was introduced.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
// Existing tasks receive the same priority default as newly created tasks.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
// Upgrade existing projects without changing any saved task priorities.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
// An empty string represents an optional, unset calendar date.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
// Preserve legacy creation order and allow moved tasks to append without changing identity.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  database.exec(`BEGIN;
    ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
    UPDATE tasks SET position = id;
    COMMIT;`);
}
const projectSelection = `SELECT id, name, archived, default_task_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND completed = 1) AS completed
  FROM projects`;
const listProjects = database.prepare(`${projectSelection} ORDER BY id`);
const findProject = database.prepare(`${projectSelection} WHERE id = ?`);
const archiveProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const createTask = database.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?))`);
const moveTask = database.prepare(`UPDATE tasks SET project_id = ?,
  position = (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?)
  WHERE project_id = ? AND id = ?`);
const setDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const setTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');

const setTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');

function taskData(task) {
  return { ...task, completed: Boolean(task.completed) };
}

const assets = new Map([
  ['/', ['index.html', 'text/html; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/task-filters.js', ['task-filters.js', 'text/javascript; charset=utf-8']],
  ['/due-dates.js', ['due-dates.js', 'text/javascript; charset=utf-8']],
  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
]);

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (pathname === '/api/projects') {
      if (request.method === 'GET') return json(response, 200, listProjects.all());
      if (request.method === 'POST') {
        const input = await readJson(request);
        const name = typeof input?.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        const result = createProject.run(name);
        return json(response, 201, findProject.get(Number(result.lastInsertRowid)));
      }
    }
    const moveMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
    if (moveMatch && request.method === 'POST') {
      const projectId = Number(moveMatch[1]);
      const taskId = Number(moveMatch[2]);
      const input = await readJson(request);
      const source = findProject.get(projectId);
      if (!source) return json(response, 404, { error: 'Project not found' });
      if (source.archived) return json(response, 409, { error: 'Archived project is read-only' });
      if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
      const destinationId = input?.destination_project_id;
      if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === projectId) {
        return json(response, 400, { error: 'Choose another active destination project' });
      }
      const destination = findProject.get(destinationId);
      if (!destination) return json(response, 404, { error: 'Destination project not found' });
      if (destination.archived) return json(response, 409, { error: 'Destination project is archived' });
      // One synchronous statement atomically transfers ownership and appends to the destination.
      moveTask.run(destinationId, destinationId, projectId, taskId);
      return json(response, 200, taskData(findTask.get(destinationId, taskId)));
    }
    const tasksMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const projectId = Number(tasksMatch[1]);
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project is read-only' });
      }
      if (!tasksMatch[2]) {
        if (request.method === 'GET') return json(response, 200, listTasks.all(projectId).map(taskData));
        if (request.method === 'POST') {
          const input = await readJson(request);
          const title = typeof input?.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          const result = createTask.run(projectId, title, project.default_task_priority, projectId);
          return json(response, 201, taskData(findTask.get(projectId, Number(result.lastInsertRowid))));
        }
      } else if (request.method === 'PATCH') {
        const taskId = Number(tasksMatch[2]);
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'due_date')) {
          if (['title', 'completed', 'priority'].some((key) => Object.hasOwn(input, key))) {
            return json(response, 400, { error: 'Due date must be a separate update' });
          }
          const date = normalizeDueDate(input.due_date);
          if (date === null) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setTaskDueDate.run(date, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (Object.hasOwn(input, 'title') || Object.hasOwn(input, 'completed')) {
            return json(response, 400, { error: 'Priority must be a separate update' });
          }
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          setTaskPriority.run(input.priority, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'title')) {
          if (Object.hasOwn(input, 'completed')) {
            return json(response, 400, { error: 'Rename and completion must be separate updates' });
          }
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') {
            return json(response, 400, { error: 'Completed must be a boolean' });
          }
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return json(response, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch) {
      const projectId = Number(projectMatch[1]);
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET') return json(response, 200, project);
      if (request.method === 'PATCH') {
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'default_task_priority')) {
          if (Object.hasOwn(input, 'name') || Object.hasOwn(input, 'archived')) {
            return json(response, 400, { error: 'Default priority must be a separate update' });
          }
          if (project.archived) return json(response, 409, { error: 'Archived project is read-only' });
          if (!['Low', 'Normal', 'High'].includes(input.default_task_priority)) {
            return json(response, 400, { error: 'Default priority must be Low, Normal, or High' });
          }
          setDefaultTaskPriority.run(input.default_task_priority, projectId);
        } else if (input && Object.hasOwn(input, 'name')) {
          if (Object.hasOwn(input, 'archived')) {
            return json(response, 400, { error: 'Rename and archive must be separate updates' });
          }
          if (project.archived) return json(response, 409, { error: 'Archived project is read-only' });
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else {
          if (typeof input?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archived must be a boolean' });
          }
          archiveProject.run(Number(input.archived), projectId);
        }
        return json(response, 200, findProject.get(projectId));
      }
    }
    if (request.method === 'GET') {
      const asset = /^\/projects\/\d+$/.test(pathname) ? assets.get('/') : assets.get(pathname);
      if (asset) {
        const content = await readFile(new URL(`./public/${asset[0]}`, import.meta.url));
        response.writeHead(200, { 'Content-Type': asset[1] });
        return response.end(content);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, mkdir, rm } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';

async function availablePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

test('projects migrate, validate, rename, archive and restore with persistent tasks and summaries', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-'));
  // Start with the original schema to exercise a real upgrade.
  await mkdir(join(directory, 'nested'));
  const legacy = new DatabaseSync(join(directory, 'nested', 'projects.sqlite'));
  legacy.exec('CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
  legacy.close();
  const port = await availablePort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'nested', 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let stderr = '';
    child.stderr.on('data', (data) => { stderr += data; });
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(stderr);
      try {
        const health = await fetch(`${base}/health`);
        assert.equal(health.status, 200);
        assert.deepEqual(await health.json(), { status: 'ok' });
        return;
      } catch {
        await new Promise((resolve) => setTimeout(resolve, 25));
      }
    }
    throw new Error(`Server did not start: ${stderr}`);
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  const list = async () => (await fetch(`${base}/api/projects`)).json();
  const create = (name) => fetch(`${base}/api/projects`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
  });
  try {
    await start();
    assert.deepEqual(await list(), []);
    for (const name of ['', '   ', null, 123]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await list(), []);
    const response = await create('  First project  ');
    assert.equal(response.status, 201);
    const first = await response.json();
    assert.equal(first.name, 'First project');
    assert.equal(first.archived, 0);
    assert.equal(first.default_task_priority, 'Normal');
    assert.equal(first.total, 0);
    assert.equal(first.completed, 0);
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await list(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/app.js', '/task-filters.js', '/due-dates.js']) {
      const asset = await fetch(`${base}${path}`);
      assert.equal(asset.status, 200);
      assert.match(asset.headers.get('content-type'), /text\/javascript/);
      assert.ok((await asset.text()).length > 0);
    }
    for (const path of ['/', `/projects/${first.id}`]) {
      const page = await fetch(`${base}${path}`);
      assert.equal(page.status, 200);
      assert.match(await page.text(), /<title>Workboard<\/title>/);
    }
    const filtersModule = await fetch(`${base}/task-filters.js`);
    assert.equal(filtersModule.status, 200);
    assert.match(filtersModule.headers.get('content-type'), /javascript/);
    assert.match(await filtersModule.text(), /export function matchesTaskFilters/);
    assert.equal((await fetch(`${base}/api/projects/999999`)).status, 404);
    assert.equal((await fetch(`${base}/api/projects`, { method: 'POST', body: '{' })).status, 400);
    const tasksUrl = `${base}/api/projects/${first.id}/tasks`;
    const otherTasksUrl = `${base}/api/projects/${second.id}/tasks`;
    const tasks = async (url = tasksUrl) => (await fetch(url)).json();
    const createTask = (title, url = tasksUrl) => fetch(url, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
    });
    const complete = (task, completed, url = tasksUrl) => fetch(`${url}/${task.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed }),
    });
    assert.deepEqual(await tasks(), []);
    for (const title of ['', ' \t\n ', null, 123]) {
      const invalid = await createTask(title);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await tasks(), []);
    const taskResponse = await createTask('  First task  ');
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    assert.equal(task.priority, 'Normal');
    assert.equal(task.due_date, '');
    const nextTask = await (await createTask('Second task')).json();
    assert.notEqual(task.id, nextTask.id);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.deepEqual(await tasks(otherTasksUrl), []);
    assert.equal((await complete(task, true, otherTasksUrl)).status, 404);
    for (const completed of [null, 1, 'true']) {
      assert.equal((await complete(task, completed)).status, 400);
    }
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await complete(task, true)).status, 200);
    task.completed = true;
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await complete(task, false)).status, 200);
    task.completed = false;
    assert.deepEqual(await tasks(), [task, nextTask]);
    await complete(task, true);
    task.completed = true;
    const otherTask = await (await createTask('Other project task', otherTasksUrl)).json();
    assert.deepEqual(await tasks(otherTasksUrl), [otherTask]);
    assert.equal((await fetch(`${base}/api/projects/999999/tasks`)).status, 404);
    assert.equal((await createTask('Missing project', `${base}/api/projects/999999/tasks`)).status, 404);
    assert.equal((await complete({ id: 999999 }, true)).status, 404);
    // Simulate the pre-priority schema with saved open and completed tasks.
    await stop();
    const prePriority = new DatabaseSync(join(directory, 'nested', 'projects.sqlite'));
    prePriority.exec('ALTER TABLE tasks DROP COLUMN priority');
    prePriority.exec('ALTER TABLE tasks DROP COLUMN due_date');
    prePriority.exec('ALTER TABLE projects DROP COLUMN default_task_priority');
    prePriority.close();
    await start();
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.deepEqual(await tasks(otherTasksUrl), [otherTask]);
    const setPriority = (task, priority, url = tasksUrl) => fetch(`${url}/${task.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority }),
    });
    for (const priority of ['', 'low', 'Urgent', null, 1]) {
      assert.equal((await setPriority(task, priority)).status, 400);
    }
    assert.equal((await setPriority(task, 'High', otherTasksUrl)).status, 404);
    assert.equal((await setPriority({ id: 999999 }, 'Low')).status, 404);
    for (const update of [{ priority: 'High', title: 'Mixed' }, { priority: 'High', completed: false }]) {
      assert.equal((await fetch(`${tasksUrl}/${task.id}`, {
        method: 'PATCH', body: JSON.stringify(update),
      })).status, 400);
    }
    assert.deepEqual(await tasks(), [task, nextTask]);
    for (const priority of ['Low', 'Normal', 'High']) {
      const saved = await setPriority(task, priority);
      assert.equal(saved.status, 200);
      task.priority = priority;
      assert.deepEqual(await saved.json(), task);
    }
    assert.equal((await setPriority(nextTask, 'Low')).status, 200);
    nextTask.priority = 'Low';
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.deepEqual(await tasks(otherTasksUrl), [otherTask]);
    const renameTask = (task, title, url = tasksUrl) => fetch(`${url}/${task.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
    });
    for (const title of ['', ' \t\n ', null, 123]) {
      const invalid = await renameTask(task, title);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await renameTask(task, 'Wrong project', otherTasksUrl)).status, 404);
    assert.equal((await renameTask({ id: 999999 }, 'Missing task')).status, 404);
    assert.equal((await fetch(`${tasksUrl}/${task.id}`, {
      method: 'PATCH', body: JSON.stringify({ title: 'Mixed', completed: false }),
    })).status, 400);
    const renamedTask = await renameTask(task, '  Renamed completed task  ');
    assert.equal(renamedTask.status, 200);
    task.title = 'Renamed completed task';
    assert.deepEqual(await renamedTask.json(), task);
    const renamedOpenTask = await renameTask(nextTask, '  Renamed open task  ');
    assert.equal(renamedOpenTask.status, 200);
    nextTask.title = 'Renamed open task';
    assert.deepEqual(await renamedOpenTask.json(), nextTask);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.deepEqual(await tasks(otherTasksUrl), [otherTask]);
    first.total = 2;
    first.completed = 1;
    second.total = 1;
    const rename = (name) => fetch(`${base}/api/projects/${first.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    for (const name of ['', ' \t\n ', null, 123]) {
      const invalid = await rename(name);
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await list(), [first, second]);
    const renamed = await rename('  Renamed project  ');
    assert.equal(renamed.status, 200);
    first.name = 'Renamed project';
    assert.deepEqual(await renamed.json(), first);
    assert.deepEqual(await list(), [first, second]);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await fetch(`${base}/api/projects/999999`, {
      method: 'PATCH', body: JSON.stringify({ name: 'Missing' }),
    })).status, 404);
    assert.equal((await fetch(`${base}/api/projects/${first.id}`, {
      method: 'PATCH', body: JSON.stringify({ name: 'Mixed', archived: true }),
    })).status, 400);
    assert.deepEqual(await list(), [first, second]);
    const archive = (archived) => fetch(`${base}/api/projects/${first.id}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived }),
    });
    for (const invalid of [null, 1, 'true']) {
      assert.equal((await archive(invalid)).status, 400);
    }
    assert.equal((await archive(true)).status, 200);
    first.archived = 1;
    assert.deepEqual(await list(), [first, second]);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.equal((await createTask('Not allowed')).status, 409);
    assert.equal((await complete(task, false)).status, 409);
    assert.equal((await rename('Blocked rename')).status, 409);
    assert.equal((await renameTask(task, 'Blocked task rename')).status, 409);
    assert.equal((await setPriority(task, 'Normal')).status, 409);
    assert.deepEqual(await tasks(), [task, nextTask]);
    assert.deepEqual(await list(), [first, second]);
